import math

def find_detach_point(b, tx, ty):
    def spiral_x(phi):
        return b * phi * math.cos(phi)

    def spiral_y(phi):
        return b * phi * math.sin(phi)

    def spiral_dx(phi):
        return b * (math.cos(phi) - phi * math.sin(phi))

    def spiral_dy(phi):
        return b * (math.sin(phi) + phi * math.cos(phi))

    def distance_squared(x1, y1, x2, y2):
        return (x1 - x2) ** 2 + (y1 - y2) ** 2

    # Initial guess for phi
    phi_min = 0
    phi_max = 1000  # Arbitrary large value to ensure we cover the spiral
    epsilon = 1e-5

    while phi_max - phi_min > epsilon:
        phi_mid = (phi_min + phi_max) / 2
        sx = spiral_x(phi_mid)
        sy = spiral_y(phi_mid)
        dx = spiral_dx(phi_mid)
        dy = spiral_dy(phi_mid)

        # Line equation from (sx, sy) in direction (dx, dy)
        # (tx - sx) = k * dx
        # (ty - sy) = k * dy
        if dx == 0:
            k = (ty - sy) / dy
        elif dy == 0:
            k = (tx - sx) / dx
        else:
            k = ((ty - sy) * dx - (tx - sx) * dy) / (dx**2 + dy**2)

        # Intersection point of the line with the spiral
        ix = sx + k * dx
        iy = sy + k * dy

        # Check if the intersection point is on the spiral
        if distance_squared(ix, iy, tx, ty) < distance_squared(sx, sy, tx, ty):
            phi_max = phi_mid
        else:
            phi_min = phi_mid

    # Final phi
    phi_final = (phi_min + phi_max) / 2
    return spiral_x(phi_final), spiral_y(phi_final)

